using System;using System.IO;using System.Text;using Frociart;
internal static class CSharpHostExamples {
 static int Main(string[] args){try{string root=args[0];foreach(var example in new[]{new[]{"FileExample","DICHIARA riga: TESTO\nAPRI_FILE LETTURA \"input.txt\"\nAPRI_FILE SCRITTURA \"output.txt\"\nMENTRE non EOF() FAI\nLEGGI_FILE riga\nSCRIVI_FILE riga\nFINE MENTRE\nCHIUDI_FILE LETTURA\nCHIUDI_FILE SCRITTURA\nSTAMPA \"copiato\""},new[]{"TurtleExample",FlowTurtle.Example},new[]{"UnicodeExample","STAMPA π\nSTAMPA \"È 🐢\""},new[]{"InputExample","DICHIARA n: REALE\nLEGGI n\nSTAMPA n+1"}}){var document=FlowPseudocode.Decode(example[1]);var text=FlowCSharp.Generate(FlowSource.Compile(document),File.ReadAllText(Path.Combine(root,"../frociart-v1-capabilities/pc/Source/CSharpRuntime.txt")),example[0]);File.WriteAllText(Path.Combine(root,example[0]+".cs"),text.Text,new UTF8Encoding(false));}Console.WriteLine("CSHARP_HOST_EXAMPLES PASS");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
